void run6(const double* restrict x0, const double* restrict c, double* restrict one, double* restrict fin, long B, long m) {
  _mm_setcsr(_mm_getcsr() | 0x8040);
  const size_t vol=216, bytes=(size_t)216*16;
  if (B<=0) return;
  if (m<=0) { memcpy(one,x0,B*bytes); memcpy(fin,x0,B*bytes); return; }
  const size_t abytes = (bytes+63)&~(size_t)63;
  double* wv = (double*)aligned_alloc(64, abytes);
  for (long b=0;b<B;b++) {
    const double* cv = c + b*vol*2;
    memcpy(wv, x0 + b*vol*2, bytes);
    for (long s=0;s<m;s++) {
      for (long x=0;x<6;x++) {
        double* pl = wv + x*72;
        for (long z0=0;z0<4;z0+=4) f6_py(pl + z0*2);
        f6_py_t(pl + 8, (__mmask8)15);
      }
      {
        __attribute__((aligned(64))) double S[48];
        for (long g=0;g<9;g++) {
          double* gl = wv + 0 + g*48;
          { double* lb = gl + 0;
            tin4(lb, lb+12, lb+24, lb+36, S+0, 1);
            _mm512_store_pd(S+32, ld4l(lb, lb+12, lb+24, lb+36, 4));
            _mm512_store_pd(S+40, ld4l(lb, lb+12, lb+24, lb+36, 5));
          }
          f6_u(S);
          { double* lb = gl + 0;
            tout4(lb, lb+12, lb+24, lb+36, S+0, 1);
            st4l(lb, lb+12, lb+24, lb+36, 4, _mm512_load_pd(S+32));
            st4l(lb, lb+12, lb+24, lb+36, 5, _mm512_load_pd(S+40));
          }
        }
      }
      f6_px(wv);
      for (long col=4;col<36;col+=4) f6_pxm(wv + col*2, wv + col*2 - 8, cv + col*2 - 8);
      f6_mq(wv + 64, cv + 64);
      if (s==0) memcpy(one + b*vol*2, wv, bytes);
    }
    memcpy(fin + b*vol*2, wv, bytes);
  }
  free(wv);
}

