void run8(const double* restrict x0, const double* restrict c, double* restrict one, double* restrict fin, long B, long m) {
  _mm_setcsr(_mm_getcsr() | 0x8040);
  const size_t vol=512, bytes=(size_t)512*16;
  if (B<=0) return;
  if (m<=0) { memcpy(one,x0,B*bytes); memcpy(fin,x0,B*bytes); return; }
  const size_t abytes = (bytes+63)&~(size_t)63;
  double* wv = (double*)aligned_alloc(64, abytes);
  for (long b=0;b<B;b++) {
    const double* cv = c + b*vol*2;
    memcpy(wv, x0 + b*vol*2, bytes);
    for (long s=0;s<m;s++) {
      for (long x=0;x<8;x++) {
        double* pl = wv + x*128;
        for (long z0=0;z0<8;z0+=4) f8_py(pl + z0*2);
      }
      {
        __attribute__((aligned(64))) double S[64];
        for (long g=0;g<16;g++) {
          double* gl = wv + 0 + g*64;
          { double* lb = gl + 0;
            tin4(lb, lb+16, lb+32, lb+48, S+0, 2);
          }
          f8_u(S);
          { double* lb = gl + 0;
            tout4(lb, lb+16, lb+32, lb+48, S+0, 2);
          }
        }
      }
      f8_px(wv);
      for (long col=4;col<64;col+=4) f8_pxm(wv + col*2, wv + col*2 - 8, cv + col*2 - 8);
      f8_mq(wv + 120, cv + 120);
      if (s==0) memcpy(one + b*vol*2, wv, bytes);
    }
    memcpy(fin + b*vol*2, wv, bytes);
  }
  free(wv);
}

